import{c as s,Q as t,j as a,m as n}from"./chunks/framework.dywCjXaF.js";const c=JSON.parse('{"title":"New & Absent Tests","description":"","frontmatter":{},"headers":[],"relativePath":"new-absent-tests.md","filePath":"new-absent-tests.md"}'),o={name:"new-absent-tests.md"};function i(r,e,l,p,h,d){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="new-absent-tests" tabindex="-1">New &amp; Absent Tests <a class="header-anchor" href="#new-absent-tests" aria-label="Permalink to &quot;New &amp; Absent Tests&quot;">​</a></h1><p>The Overview tab surfaces two coverage signals after each run: <strong>New Tests</strong> and <strong>Absent Tests</strong>. Understanding what they mean — and why a test might appear in either list — helps you act on the right signal and ignore the noise.</p><nav class="table-of-contents"><ul><li><a href="#what-is-a-new-test">What is a &quot;New&quot; test?</a><ul><li><a href="#possible-reasons">Possible reasons</a></li><li><a href="#what-the-report-shows">What the report shows</a></li><li><a href="#what-to-do">What to do</a></li></ul></li><li><a href="#what-is-an-absent-test">What is an &quot;Absent&quot; test?</a><ul><li><a href="#possible-reasons-1">Possible reasons</a></li><li><a href="#what-the-report-shows-1">What the report shows</a></li><li><a href="#what-to-do-1">What to do</a></li></ul></li><li><a href="#the-3-run-aging-rule">The 3-run aging rule</a><ul><li><a href="#lifecycle-example">Lifecycle example</a></li><li><a href="#what-aged-out-means">What &quot;aged out&quot; means</a></li></ul></li><li><a href="#scenario-walkthroughs">Scenario walkthroughs</a><ul><li><a href="#scenario-1-—-test-genuinely-deleted">Scenario 1 — Test genuinely deleted</a></li><li><a href="#scenario-2-—-test-renamed">Scenario 2 — Test renamed</a></li><li><a href="#scenario-3-—-test-temporarily-skipped">Scenario 3 — Test temporarily skipped</a></li><li><a href="#scenario-4-—-deleted-test-restored">Scenario 4 — Deleted test restored</a></li></ul></li><li><a href="#key-points-to-remember">Key points to remember</a></li></ul></nav><hr><h2 id="what-is-a-new-test" tabindex="-1">What is a &quot;New&quot; test? <a class="header-anchor" href="#what-is-a-new-test" aria-label="Permalink to &quot;What is a &quot;New&quot; test?&quot;">​</a></h2><p>A test is flagged as <strong>New</strong> when it appears in the current run but has <strong>never been seen before</strong> in any previous run.</p><h3 id="possible-reasons" tabindex="-1">Possible reasons <a class="header-anchor" href="#possible-reasons" aria-label="Permalink to &quot;Possible reasons&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Reason</th><th>Description</th></tr></thead><tbody><tr><td>✅ Genuinely new</td><td>A developer added a new test case to the suite</td></tr><tr><td>⚠️ Renamed</td><td>An existing test was renamed — the old name disappears (absent), the new name appears (new)</td></tr><tr><td>⚠️ Moved to a different file</td><td>The test moved files — its <code>fullName</code> changes, so it looks new</td></tr></tbody></table><h3 id="what-the-report-shows" tabindex="-1">What the report shows <a class="header-anchor" href="#what-the-report-shows" aria-label="Permalink to &quot;What the report shows&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NEW TESTS  1 test</span></span>
<span class="line"><span>┌────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ ✓  Login with SSO                             [Chromium]       │</span></span>
<span class="line"><span>│    First time in this run — new test, or renamed / moved       │</span></span>
<span class="line"><span>│    from an existing one                                         │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="what-to-do" tabindex="-1">What to do <a class="header-anchor" href="#what-to-do" aria-label="Permalink to &quot;What to do&quot;">​</a></h3><ol><li><strong>Confirm it&#39;s intentional</strong> — check your recent git changes</li><li><strong>If it&#39;s a rename</strong> — the old name will appear in Absent Tests; both will naturally age out within 3 runs</li><li><strong>If it&#39;s genuinely new</strong> — no action needed; history starts accumulating from this run</li></ol><hr><h2 id="what-is-an-absent-test" tabindex="-1">What is an &quot;Absent&quot; test? <a class="header-anchor" href="#what-is-an-absent-test" aria-label="Permalink to &quot;What is an &quot;Absent&quot; test?&quot;">​</a></h2><p>A test is flagged as <strong>Absent</strong> when it ran in one or more previous runs but is <strong>missing from the current run</strong>.</p><h3 id="possible-reasons-1" tabindex="-1">Possible reasons <a class="header-anchor" href="#possible-reasons-1" aria-label="Permalink to &quot;Possible reasons&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Reason</th><th>Description</th></tr></thead><tbody><tr><td>✅ Genuinely deleted</td><td>A developer intentionally removed the test</td></tr><tr><td>⚠️ Renamed</td><td>The test was renamed — old name shows as absent, new name shows as new</td></tr><tr><td>⚠️ Moved to a different file</td><td>The test moved files — its <code>fullName</code> changed, old entry shows as absent</td></tr><tr><td>⚠️ Skipped / filtered</td><td>The test was excluded by a tag filter or marked <code>skip</code> for this run</td></tr></tbody></table><h3 id="what-the-report-shows-1" tabindex="-1">What the report shows <a class="header-anchor" href="#what-the-report-shows-1" aria-label="Permalink to &quot;What the report shows&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ABSENT TESTS  1 test</span></span>
<span class="line"><span>┌────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ ✓  Login with password                        [Firefox]        │</span></span>
<span class="line"><span>│    Not seen in 2 consecutive runs · Last seen: May 28, 02:01   │</span></span>
<span class="line"><span>│    May be deleted, renamed, or moved — verify recent changes   │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="what-to-do-1" tabindex="-1">What to do <a class="header-anchor" href="#what-to-do-1" aria-label="Permalink to &quot;What to do&quot;">​</a></h3><ol><li><strong>Check recent changes</strong> — was the test deleted, renamed, or moved?</li><li><strong>If intentionally deleted</strong> — it will age out automatically after 3 consecutive absent runs</li><li><strong>If it&#39;s a skip</strong> — check for <code>test.skip</code> or tag filters in your test config</li><li><strong>If it&#39;s a rename</strong> — the new name appears in New Tests; both lists self-clear within 3 runs</li></ol><hr><h2 id="the-3-run-aging-rule" tabindex="-1">The 3-run aging rule <a class="header-anchor" href="#the-3-run-aging-rule" aria-label="Permalink to &quot;The 3-run aging rule&quot;">​</a></h2><p>Sarva-Varadi cannot automatically distinguish between a deleted test, a renamed test, or a moved test — they all look the same: the <code>testId</code> (based on test name + file path) is no longer present in the run.</p><p>To avoid permanent noise in the Absent section, absent tests are <strong>aged out</strong> after <strong>3 consecutive runs</strong> without appearing.</p><h3 id="lifecycle-example" tabindex="-1">Lifecycle example <a class="header-anchor" href="#lifecycle-example" aria-label="Permalink to &quot;Lifecycle example&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run 20:  &quot;Login Test&quot;  ✓ PASSED   → normal test, in history</span></span>
<span class="line"><span>Run 21:  &quot;Login Test&quot;  absent     → shown in Absent (not seen in 1 run)</span></span>
<span class="line"><span>Run 22:  &quot;Login Test&quot;  absent     → shown in Absent (not seen in 2 runs)</span></span>
<span class="line"><span>Run 23:  &quot;Login Test&quot;  absent     → shown in Absent (not seen in 3 runs)</span></span>
<span class="line"><span>Run 24:  &quot;Login Test&quot;  absent     → AGED OUT — no longer shown in Absent section</span></span>
<span class="line"><span>Run 25+: still absent             → remains aged out (silent)</span></span></code></pre></div><h3 id="what-aged-out-means" tabindex="-1">What &quot;aged out&quot; means <a class="header-anchor" href="#what-aged-out-means" aria-label="Permalink to &quot;What &quot;aged out&quot; means&quot;">​</a></h3><p>Aged out = <strong>removed from the Absent display only</strong>. The underlying history data in <code>runs.json</code> is fully preserved.</p><p>If the test comes back under the same name, its complete history is automatically restored on the very next run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run 30:  &quot;Login Test&quot;  ✓ PASSED   → back in Tests list with full history from runs 1–20 intact ✅</span></span></code></pre></div><hr><h2 id="scenario-walkthroughs" tabindex="-1">Scenario walkthroughs <a class="header-anchor" href="#scenario-walkthroughs" aria-label="Permalink to &quot;Scenario walkthroughs&quot;">​</a></h2><h3 id="scenario-1-—-test-genuinely-deleted" tabindex="-1">Scenario 1 — Test genuinely deleted <a class="header-anchor" href="#scenario-1-—-test-genuinely-deleted" aria-label="Permalink to &quot;Scenario 1 — Test genuinely deleted&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run 10:  &quot;Checkout test&quot;  ✓ PASSED</span></span>
<span class="line"><span>Run 11:  Test deleted from codebase</span></span>
<span class="line"><span>Run 11:  &quot;Checkout test&quot;  ABSENT  (1 run) → shown with hint</span></span>
<span class="line"><span>Run 12:  &quot;Checkout test&quot;  ABSENT  (2 runs) → shown with hint</span></span>
<span class="line"><span>Run 13:  &quot;Checkout test&quot;  ABSENT  (3 runs) → shown with hint</span></span>
<span class="line"><span>Run 14:  AGED OUT → no longer shown</span></span></code></pre></div><p><strong>Action:</strong> No action needed. Aged out cleanly after 3 runs.</p><hr><h3 id="scenario-2-—-test-renamed" tabindex="-1">Scenario 2 — Test renamed <a class="header-anchor" href="#scenario-2-—-test-renamed" aria-label="Permalink to &quot;Scenario 2 — Test renamed&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run 10:  &quot;Login with password&quot;  ✓ PASSED</span></span>
<span class="line"><span>Run 11:  Developer renames to &quot;Login with credentials&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Run 11:  NEW    &quot;Login with credentials&quot;  ← new name, first appearance</span></span>
<span class="line"><span>         ABSENT &quot;Login with password&quot;     ← old name, not seen (1 run)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Run 12:  &quot;Login with credentials&quot;  runs normally (no longer &quot;new&quot;)</span></span>
<span class="line"><span>         ABSENT &quot;Login with password&quot; — not seen (2 runs)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Run 13:  ABSENT &quot;Login with password&quot; — not seen (3 runs)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Run 14:  &quot;Login with password&quot; AGED OUT — no longer shown</span></span>
<span class="line"><span>         &quot;Login with credentials&quot; builds its own history from run 11 onwards</span></span></code></pre></div><p><strong>Action:</strong> Verify the rename was intentional. Both signals resolve automatically.</p><hr><h3 id="scenario-3-—-test-temporarily-skipped" tabindex="-1">Scenario 3 — Test temporarily skipped <a class="header-anchor" href="#scenario-3-—-test-temporarily-skipped" aria-label="Permalink to &quot;Scenario 3 — Test temporarily skipped&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run 15:  &quot;Payment test&quot;  skipped (marked test.skip in code)</span></span>
<span class="line"><span>Run 15:  &quot;Payment test&quot; → ABSENT (it didn&#39;t execute)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Run 16:  Developer removes test.skip</span></span>
<span class="line"><span>Run 16:  &quot;Payment test&quot;  ✓ PASSED → back in Tests list, absent count resets</span></span></code></pre></div><p><strong>Action:</strong> Check for <code>test.skip</code> or filter flags. Once the test runs again, it leaves the absent list immediately.</p><hr><h3 id="scenario-4-—-deleted-test-restored" tabindex="-1">Scenario 4 — Deleted test restored <a class="header-anchor" href="#scenario-4-—-deleted-test-restored" aria-label="Permalink to &quot;Scenario 4 — Deleted test restored&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run 20:  &quot;Search test&quot;  ✓ PASSED</span></span>
<span class="line"><span>Runs 21–23: Test deleted → aged out of Absent after run 23</span></span>
<span class="line"><span>Run 30:  Developer restores the test with same name</span></span>
<span class="line"><span>Run 30:  &quot;Search test&quot;  ✓ PASSED → back in Tests list</span></span>
<span class="line"><span>         Full history from runs 1–20 automatically restored ✅</span></span></code></pre></div><p><strong>Action:</strong> No action needed. History is never deleted, only the Absent display entry ages out.</p><hr><h2 id="key-points-to-remember" tabindex="-1">Key points to remember <a class="header-anchor" href="#key-points-to-remember" aria-label="Permalink to &quot;Key points to remember&quot;">​</a></h2><ul><li>Both <strong>New</strong> and <strong>Absent</strong> signals can indicate a rename or file move — they appear as a pair (one absent, one new) in the same run</li><li>Sarva-Varadi tracks by <strong>test name + file path</strong> — there is no automatic rename detection</li><li>The <strong>3-run aging</strong> window gives you time to investigate before the signal disappears</li><li><strong>History data is always preserved</strong> — aging out only affects the Absent display, not the underlying data</li><li>If a test is skipped (not just absent), it won&#39;t appear in the absent list — only tests that truly don&#39;t execute show as absent</li></ul>`,51)])])}const g=s(o,[["render",i]]);export{c as __pageData,g as default};
